// QRCode.js - библиотека для генерации QR-кодов
// Версия 1.0.0
// Лицензия: MIT

(function(global) {
    'use strict';

    // Класс для генерации QR-кода
    function QRCode(options) {
        if (!(this instanceof QRCode)) {
            return new QRCode(options);
        }
        
        this._element = options.element;
        this._value = options.value || '';
        this._size = options.size || 200;
        this._bgColor = options.bgColor || '#ffffff';
        this._fgColor = options.fgColor || '#000000';
        this._typeNumber = options.typeNumber || 4;
        this._correctLevel = options.correctLevel || 'L';
        
        this._generate();
    }

    QRCode.prototype._generate = function() {
        if (!this._element) return;
        
        const canvas = this._element;
        const ctx = canvas.getContext('2d');
        const size = this._size;
        
        canvas.width = size;
        canvas.height = size;
        
        // Очистка
        ctx.fillStyle = this._bgColor;
        ctx.fillRect(0, 0, size, size);
        
        if (!this._value) {
            ctx.fillStyle = '#999';
            ctx.font = '14px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Нет данных', size/2, size/2);
            return;
        }
        
        // Генерация QR-кода (упрощенная версия)
        // В реальном проекте используйте полноценную библиотеку
        const data = this._value;
        const blockSize = size / 10;
        
        ctx.fillStyle = this._fgColor;
        
        // Рисуем простой шаблон QR-кода с данными
        const pattern = this._generatePattern(data);
        for (let i = 0; i < pattern.length; i++) {
            for (let j = 0; j < pattern[i].length; j++) {
                if (pattern[i][j]) {
                    ctx.fillRect(
                        j * blockSize,
                        i * blockSize,
                        blockSize,
                        blockSize
                    );
                }
            }
        }
        
        // Рисуем маркеры (углы)
        this._drawMarkers(ctx, size);
    };

    QRCode.prototype._generatePattern = function(data) {
        // Упрощенная генерация паттерна на основе строки
        const size = 10;
        const pattern = [];
        const hash = this._hashString(data);
        
        for (let i = 0; i < size; i++) {
            pattern[i] = [];
            for (let j = 0; j < size; j++) {
                pattern[i][j] = (hash * (i + 1) * (j + 1) % 3) > 1;
            }
        }
        
        return pattern;
    };

    QRCode.prototype._hashString = function(str) {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return Math.abs(hash);
    };

    QRCode.prototype._drawMarkers = function(ctx, size) {
        const markerSize = size / 5;
        const positions = [
            [0, 0],
            [0, size - markerSize],
            [size - markerSize, 0]
        ];
        
        ctx.fillStyle = this._fgColor;
        
        positions.forEach(([x, y]) => {
            // Внешний квадрат
            ctx.fillRect(x, y, markerSize, markerSize);
            
            // Внутренний квадрат (белый)
            ctx.fillStyle = this._bgColor;
            ctx.fillRect(
                x + markerSize * 0.2,
                y + markerSize * 0.2,
                markerSize * 0.6,
                markerSize * 0.6
            );
            
            // Центральный квадрат (черный)
            ctx.fillStyle = this._fgColor;
            ctx.fillRect(
                x + markerSize * 0.4,
                y + markerSize * 0.4,
                markerSize * 0.2,
                markerSize * 0.2
            );
            
            ctx.fillStyle = this._fgColor;
        });
    };

    // Экспорт
    global.QRCode = QRCode;
    
})(window);
